import type * as D from './types.d.ts'

export interface Def {
  service: D.DefinitionsService
  network: D.DefinitionsNetwork
  volume: D.DefinitionsVolume
  secret: D.DefinitionsSecret
  config: D.DefinitionsConfig
}

type DefInit<T, C> = T | ((c: C) => T) | ((c: C) => Promise<T>)

export type Context<N extends string> = {
  name: N
  build?: boolean
}

const RESOURCE: unique symbol = Symbol.for('@pingid/lib/ship:Resource')
export interface ResourceDef<K extends keyof Def = keyof Def, N extends string = string, T extends Def[K] = Def[K]> {
  [RESOURCE]: true
  type: K
  name: N
  init: () => Promise<T>
}

const resorce =
  <S extends keyof Def>(type: S) =>
  <N extends string, const T extends Def[S]>(name: N, def: DefInit<T, Context<N>>): ResourceDef<S, N, T> => {
    const init = async () => (typeof def !== 'function' ? def : await def({ name }))
    return { [RESOURCE]: true, type, name, init }
  }

export const Service = resorce('service')
export type Service<N extends string = string, T extends Def['service'] = Def['service']> = ResourceDef<'service', N, T>

export const Network = resorce('network')
export type Network<N extends string = string, T extends Def['network'] = Def['network']> = ResourceDef<'network', N, T>

export const Volume = resorce('volume')
export type Volume<N extends string = string, T extends Def['volume'] = Def['volume']> = ResourceDef<'volume', N, T>

export const Secret = resorce('secret')
export type Secret<N extends string = string, T extends Def['secret'] = Def['secret']> = ResourceDef<'secret', N, T>

export const Config = resorce('config')
export type Config<N extends string = string, T extends Def['config'] = Def['config']> = ResourceDef<'config', N, T>

const COMPOSE: unique symbol = Symbol.for('@pingid/lib/ship:Compose')

export type Compose<T extends ResourceDef, N extends string = string> = {
  name: N
  [COMPOSE]: true
  resources: T[]
} & Mapped<T>

export const Compose = <T extends (ResourceDef | Compose<any>)[]>(
  name: string,
  resources: T | (() => T),
): Compose<Extract<T[number], ResourceDef>> => {
  let c: { resources: ResourceDef[]; groups: any } | undefined = undefined
  const get = () => {
    if (c === undefined) c = grouped(resources)
    return c!
  }
  const o = {
    name,
    [COMPOSE]: true,
    get resources() {
      return get().resources
    },
    get services() {
      return get().groups.service
    },
    get networks() {
      return get().groups.network
    },
    get volumes() {
      return get().groups.volume
    },
    get secrets() {
      return get().groups.secret
    },
    get configs() {
      return get().groups.config
    },
  }
  return o as any
}

type Mapped<T extends ResourceDef> = { [K in T['type']]: { [N in T['name']]: T } }

export type Var<T extends any = any, N extends string = string> = {
  name: N
  provide: (value: T) => void
  get: () => T
}
export const Var = <T, N extends string = string>(name: N): Var<T, N> => {
  const provide = (value: T) => registry().set(name, value)
  const get = () => {
    if (registry().has(name)) return registry().get(name)
    throw new Error(`Var ${name} not found`)
  }
  return { name, provide, get }
}

let reg: Map<string, any> | undefined
const registry = () => {
  if (reg === undefined) reg = new Map()
  return reg
}

const isResource = (r: object): r is ResourceDef => RESOURCE in r && r[RESOURCE] === true

const grouped = <T extends (ResourceDef | Compose<any>)[]>(resources: T | (() => T)) => {
  const flat = (typeof resources === 'function' ? resources() : resources)
    .map((r) => (isResource(r) ? r : r.resources))
    .flat() as ResourceDef[]
  const groups: any = {}
  for (const r of flat) {
    if (!groups[r.type]) groups[r.type] = {}
    groups[r.type][r.name] = r
  }
  return { resources: flat, ...groups }
}

export const Resolve = async <T extends Compose<any>>(c: T) => {
  const g = await resolve(c.resources)
  return { name: c.name, ...g }
}

const resolve = async <T extends (ResourceDef | Compose<any>)[]>(resource: T) => {
  const out: any = {}
  for (const r of resource) {
    if (isResource(r)) {
      if (!out[r.type]) out[r.type] = {}
      out[r.type][r.name] = await r.init()
    } else {
      const res = await resolve(r.resources)
      for (const [k, v] of Object.entries(res)) {
        if (!out[k]) out[k] = {}
        for (const [n, value] of Object.entries(v as any)) out[k][n] = value
      }
    }
  }
  return out
}
